        super.setValues(new int[size()]);
    }

test_prefix:
public void testClear_2_oe() {
    MutablePeriod test = new MutablePeriod(1, 2, 3, 4, 5, 6, 7, 8);
    test.clear();
    // removed other assertion

    test = new MutablePeriod(1, 2, 0, 4, 5, 6, 7, 8, PeriodType.yearMonthDayTime());
    test.clear();
    assertEquals(new MutablePeriod(PeriodType.yearMonthDayTime()),test);
}

mut_method_definition:
public static PeriodType yearMonthDayTime() {
        PeriodType type = cYMDTime;
        if (type == null) {
            type = new PeriodType(
                "YearMonthDayTime",
                new DurationFieldType[] {
                    DurationFieldType.years(), DurationFieldType.months(),
                    DurationFieldType.days(),
                    DurationFieldType.hours(), DurationFieldType.minutes(),
                    DurationFieldType.seconds(), DurationFieldType.millis(),
                },
                new int[] { 0, 1, -1, 2, 3, 4, 5, 6, }
            );
            cYMDTime = type;
        }
        return type;
    }

